import{_ as i,a0 as l,w as d,s as o,ao as r,I as p,x as n,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用 df 命令查看 Linux 上的可用磁盤空間 | LCTT x X-CMD","titleTemplate":false,"description":"使用 df 命令查看 Linux 上的可用磁盤空間 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 df 命令查看 Linux 上的可用磁盤空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 df 命令查看 Linux 上的可用磁盤空間 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210729 Use df to check free disk space on Linux","title":"使用 df 命令查看 Linux 上的可用磁盤空間","tag":"202108","desc":""},"relativePath":"202108/20210729 Use df to check free disk space on Linux.md","filePath":"[post].md"}'),u={name:"202108/20210729 Use df to check free disk space on Linux.md"};function f(h,s,c,k,m,g){const a=l("Link");return d(),o("div",null,[s[18]||(s[18]=r(`<h1 id="使用-df-命令查看-linux-上的可用磁盤空間" tabindex="-1">使用 df 命令查看 Linux 上的可用磁盤空間 <a class="header-anchor" href="#使用-df-命令查看-linux-上的可用磁盤空間" aria-label="Permalink to “使用 df 命令查看 Linux 上的可用磁盤空間”">​</a></h1><blockquote><p>利用 df 命令查看 Linux 磁盤還剩多少空間。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/04/110742netskjccb5vzvujk.jpg" alt=""></p><p>磁盤空間已經不像計算機早期那樣珍貴，但無論你有多少磁盤空間，總有耗盡的可能。計算機需要一些磁盤空間才能啓動運行，所以為了確保你沒有在無意間用盡了所有的硬盤空間，偶爾檢查一下是非常必要的。在 Linux 終端，你可以用 <code>df</code> 命令來做這件事。</p><p><code>df</code> 命令可以顯示文件系統中可用的磁盤空間。</p><p>要想使輸出結果易於閲讀，你可以加上 <code>--human-readable</code>（或其簡寫 <code>-h</code>）選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df --human-readable</span></span>
<span class="line"><span>Filesystem      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/sda1       1.0T  525G  500G  52% /</span></span></code></pre></div><p>在這個例子中，計算機的磁盤已經用了 52%，還有 500 GB 可用空間。</p><p>由於 Linux 從整體上看待所有掛載設備的文件系統，<code>df</code> 命令會展示出連接到計算機上的每個存儲設備的詳細信息。如果你有很多磁盤，那麼輸出結果將會反映出來：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df --human-readable</span></span>
<span class="line"><span>Filesystem      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/root       110G   45G   61G  43% /</span></span>
<span class="line"><span>devtmpfs         12G     0   12G   0% /dev</span></span>
<span class="line"><span>tmpfs            12G  848K   12G   1% /run</span></span>
<span class="line"><span>/dev/sda1       1.6T  1.3T  191G  87% /home</span></span>
<span class="line"><span>/dev/sdb1       917G  184G  687G  22% /penguin</span></span>
<span class="line"><span>/dev/sdc1        57G   50G  4.5G  92% /sneaker</span></span>
<span class="line"><span>/dev/sdd1       3.7T  2.4T  1.3T  65% /tux</span></span></code></pre></div><p>在這個例子中，計算機的 <code>/home</code> 目錄已經用了 87%，剩下 191 GB 的可用空間。</p><h3 id="查看總的可用磁盤空間" tabindex="-1">查看總的可用磁盤空間 <a class="header-anchor" href="#查看總的可用磁盤空間" aria-label="Permalink to “查看總的可用磁盤空間”">​</a></h3><p>如果你的文件系統確實很複雜，而你希望看到所有磁盤的總空間，可以使用 <code>--total</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df --human-readable --total</span></span>
<span class="line"><span>Filesystem      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/root       110G   45G   61G  43% /</span></span>
<span class="line"><span>devtmpfs         12G     0   12G   0% /dev</span></span>
<span class="line"><span>tmpfs            12G  848K   12G   1% /run</span></span>
<span class="line"><span>/dev/sda1       1.6T  1.3T  191G  87% /home</span></span>
<span class="line"><span>/dev/sdb1       917G  184G  687G  22% /penguin</span></span>
<span class="line"><span>/dev/sdc1        57G   50G  4.5G  92% /sneaker</span></span>
<span class="line"><span>/dev/sdd1       3.7T  2.4T  1.3T  65% /tux</span></span>
<span class="line"><span>total           6.6T  4.0T  2.5T  62% -</span></span></code></pre></div><p>輸出的最後一行展示了文件系統的總空間、已用總空間、可用總空間。</p><h3 id="查看磁盤空間使用情況" tabindex="-1">查看磁盤空間使用情況 <a class="header-anchor" href="#查看磁盤空間使用情況" aria-label="Permalink to “查看磁盤空間使用情況”">​</a></h3>`,16)),p("p",null,[s[1]||(s[1]=n("如果你想大概瞭解哪些文件佔用了磁盤空間，請閲讀我們關於 ",-1)),e(a,{href:"https://opensource.com/article/21/7/check-used-disk-space-linux-du"},{default:t(()=>[...s[0]||(s[0]=[n("du 命令",-1)])]),_:1}),s[2]||(s[2]=n(" 的文章。",-1))]),s[19]||(s[19]=p("hr",null,null,-1)),p("p",null,[s[4]||(s[4]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/21/7/check-disk-space-linux-df"},{default:t(()=>[...s[3]||(s[3]=[n("https://opensource.com/article/21/7/check-disk-space-linux-df",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[5]||(s[5]=[n("Seth Kenlon",-1)])]),_:1}),s[10]||(s[10]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 譯者：",-1)),e(a,{href:"https://github.com/piaoshi"},{default:t(()=>[...s[7]||(s[7]=[n("piaoshi",-1)])]),_:1}),s[12]||(s[12]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[n("Linux中國",-1)])]),_:1}),s[17]||(s[17]=n(" 榮譽推出",-1))])])}const G=i(u,[["render",f]]);export{T as __pageData,G as default};
